insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_45_v1'
from (values
('127.254.d.7',3,'After a covered fire, what should a policyholder do first in the claims process?','["Report the loss to the insurer promptly", "Repair everything and discard the evidence", "Wait until next year to report it", "Cancel the policy"]'::jsonb,0,'Prompt notice starts the claim.','original'),
('127.254.d.7',4,'In the claims process, an adjuster''s main job is to:','["Set the premium rate", "Investigate the loss and estimate the amount owed", "Audit the insurer''s books", "Sell new policies"]'::jsonb,1,'Adjusters evaluate claims.','original'),
('127.254.d.9',3,'Which action best helps protect a customer''s personal data at an insurance office?','["Emailing records to anyone who asks", "Leaving screens unlocked", "Locking files and limiting who can view client records", "Posting policy numbers in the lobby"]'::jsonb,2,'Access controls protect data.','original'),
('127.254.d.9',4,'An agent receives an email asking for a client''s Social Security number from an unverified sender. The best response is to:','["Reply with the client''s birthday too", "Send the number quickly", "Forward it to coworkers", "Refuse and verify the request through a trusted channel"]'::jsonb,3,'Verify before sharing sensitive data.','original'),
('127.254.d.1.A',3,'The main purpose of the insurance industry is to:','["Transfer financial risk from individuals to a larger pool", "Lend money for homes", "Eliminate all accidents", "Guarantee profits for customers"]'::jsonb,0,'Insurance spreads risk.','original'),
('127.254.d.1.A',4,'The law of large numbers helps insurers because with many policyholders, losses become:','["Impossible to estimate", "More predictable", "Less predictable", "Equal for everyone"]'::jsonb,1,'Larger pools stabilize loss estimates.','original'),
('127.254.d.1.B',3,'Which auto coverage pays for damage to your own car after a collision with another car or object?','["Bodily injury liability", "Comprehensive coverage", "Collision coverage", "Uninsured motorist coverage"]'::jsonb,2,'Collision pays for your vehicle''s damage.','original'),
('127.254.d.1.B',4,'A driver''s policy lists 50/100/25 liability limits. The 25 refers to the maximum payout, in thousands, for:','["Medical bills per person", "Collision repairs to the insured car", "Towing", "Property damage to others per accident"]'::jsonb,3,'The three numbers are per-person injury, per-accident injury, and property damage.','original'),
('127.254.d.1.C',3,'A homeowner''s policy generally covers the dwelling and also:','["Personal belongings and liability for injuries on the property", "Earthquake damage", "Flood damage from rising rivers", "Car accidents"]'::jsonb,0,'Standard policies include contents and liability but exclude floods and quakes.','original'),
('127.254.d.1.C',4,'A personal umbrella policy is designed to provide:','["Cheaper car repairs", "Extra liability coverage above home and auto limits", "Rain damage coverage", "Health benefits"]'::jsonb,1,'Umbrellas add liability limits.','original'),
('127.254.d.1.D',3,'Why do homeowners in low-lying areas often buy a separate flood policy?','["Flood is always included", "Floods never occur", "Standard homeowner''s policies usually exclude flood damage", "Banks forbid it"]'::jsonb,2,'Flood requires separate coverage.','original'),
('127.254.d.1.D',4,'Earthquake damage is typically covered by:','["Workers'' compensation", "Health insurance", "The standard auto policy", "An added endorsement or a separate policy"]'::jsonb,3,'Earthquake coverage is an add-on.','original'),
('127.254.d.1.E',3,'Commercial property insurance protects a business against loss of its:','["Buildings, equipment, and inventory", "Employees'' health", "Customers'' loyalty", "Owner''s life"]'::jsonb,0,'It covers physical business assets.','original'),
('127.254.d.1.E',4,'A bakery''s oven is destroyed by fire. Which policy is most likely to pay to replace it?','["Life insurance", "Commercial property insurance", "Disability insurance", "Workers'' compensation"]'::jsonb,1,'Equipment loss falls under property coverage.','original'),
('127.254.d.1.F',3,'A customer slips on a wet floor in a store and sues. Which policy responds?','["Commercial property", "Term life", "Commercial general liability", "Title insurance"]'::jsonb,2,'Liability covers injuries to others.','original'),
('127.254.d.1.F',4,'Commercial liability insurance protects a business from financial loss when it is:','["Out of inventory", "Short on cash", "Late on rent", "Held legally responsible for injury or damage to others"]'::jsonb,3,'It pays for legal responsibility.','original'),
('127.254.d.1.G',3,'Title insurance protects a property buyer or lender against:','["Defects or disputes in the ownership record", "Rising taxes", "Roof leaks", "Fire damage"]'::jsonb,0,'Title policies cover ownership claims.','original'),
('127.254.d.1.G',4,'Unlike most insurance, title insurance is typically bought:','["After a fire", "Once at closing for past defects", "Each year", "Every month"]'::jsonb,1,'It covers problems that already exist.','original'),
('127.254.d.1.H',3,'Which coverage helps pay for extended care in a nursing home or at home for people who cannot do daily tasks?','["Auto insurance", "Title insurance", "Long-term care insurance", "Renter''s insurance"]'::jsonb,2,'LTC pays for custodial care.','original'),
('127.254.d.1.H',4,'Cancer insurance is a supplemental policy that typically pays:','["Tuition", "Car repairs", "Property taxes", "A cash benefit after a cancer diagnosis or treatment"]'::jsonb,3,'It supplements health coverage.','original'),
('127.254.d.1.I',3,'Medicare is mainly health coverage for:','["People 65 and older and certain younger people with disabilities", "Only federal workers", "Everyone under 18", "Only veterans"]'::jsonb,0,'Medicare is age and disability based.','original'),
('127.254.d.1.I',4,'Medicaid differs from Medicare because Medicaid is:','["Fully private", "Jointly funded by states and the federal government for low-income people", "Only for retirees", "Only for veterans"]'::jsonb,1,'Medicaid is need based.','original'),
('127.254.d.1.J',3,'Unemployment insurance provides:','["Retirement income", "Health coverage", "Temporary income to eligible workers who lose a job through no fault of their own", "Permanent pay raises"]'::jsonb,2,'It replaces some income during job loss.','original'),
('127.254.d.1.J',4,'Unemployment insurance benefits are generally paid for:','["Forever", "The rest of the worker''s life", "Exactly one day", "A limited number of weeks while the worker looks for a new job"]'::jsonb,3,'Benefits are time limited.','original'),
('127.254.d.1.K',3,'Workers'' compensation covers employees who:','["Are injured or become ill because of their job", "Move away", "Retire early", "Lose a pet"]'::jsonb,0,'It covers work-related injuries.','original'),
('127.254.d.1.K',4,'In exchange for workers'' compensation benefits, an injured employee usually gives up the right to:','["A new job", "Sue the employer for the injury", "Wages", "Medical care"]'::jsonb,1,'It is generally an exclusive remedy.','original'),
('127.254.d.1.L',3,'Disability insurance is designed to replace part of a worker''s:','["Taxes", "Insurance premiums", "Paycheck if illness or injury prevents working", "Rent"]'::jsonb,2,'It protects earning ability.','original'),
('127.254.d.1.L',4,'A policy with a 90-day elimination period begins paying benefits:','["Never", "On day 1", "After 90 years", "After 90 days of disability"]'::jsonb,3,'The elimination period is a waiting time.','original'),
('127.254.d.1.M',3,'Which life insurance provides coverage for a set number of years with no cash value?','["Term", "Variable", "Whole", "Universal"]'::jsonb,0,'Term covers a defined period only.','original'),
('127.254.d.1.M',4,'Group life insurance is commonly offered through:','["A car dealer", "An employer or organization", "A bank branch", "A school lunch program"]'::jsonb,1,'Groups buy coverage together.','original'),
('127.254.d.1.N',3,'The cash value in a whole life policy can be used to:','["Pay no premium forever automatically", "Cancel taxes", "Borrow against the policy", "Avoid death benefits"]'::jsonb,2,'Cash value can be borrowed against.','original'),
('127.254.d.1.N',4,'In estate planning, a life insurance death benefit can help heirs:','["Cancel debts automatically", "Skip probate always", "Avoid grieving", "Pay estate costs and taxes without selling assets"]'::jsonb,3,'Proceeds provide liquidity.','original'),
('127.254.d.1.O',3,'One way insurers earn money besides collecting premiums is by:','["Investing the premiums before claims are paid", "Charging customers twice", "Printing money", "Avoiding all claims"]'::jsonb,0,'Investment income is a major source.','original'),
('127.254.d.1.O',4,'Underwriting profit occurs when premiums collected are:','["Less than claims paid", "Greater than claims and expenses paid", "Lower than reserves", "Equal to tax owed"]'::jsonb,1,'Premiums exceed losses and costs.','original'),
('127.254.d.1.P',3,'State risk pool programs mainly help people who:','["Own large yachts", "Prefer cash", "Cannot get coverage in the private market", "Have no income"]'::jsonb,2,'Pools offer coverage of last resort.','original'),
('127.254.d.1.P',4,'A state high-risk pool is typically funded through:','["Parking fines", "Lottery tickets", "Library fees", "Premiums, assessments on insurers, and state funds"]'::jsonb,3,'Funding is shared.','original'),
('127.254.d.1.Q',3,'Cyber or hacker insurance helps a business recover costs after:','["A data breach or cyberattack", "A broken window only", "A snowstorm", "A lost lease"]'::jsonb,0,'It covers cyber losses.','original'),
('127.254.d.1.Q',4,'Pet insurance typically reimburses owners for part of:','["Pet food always", "Veterinary bills", "Grooming only", "Pet adoption fees only"]'::jsonb,1,'It covers vet care.','original'),
('127.254.d.2.A',3,'To sell insurance in Texas, an agent generally must:','["Own a bank", "Be a lawyer", "Pass a state exam and hold a license", "Have no training"]'::jsonb,2,'Agents are licensed by the state.','original'),
('127.254.d.2.A',4,'Designations such as CPCU or CLU show that an insurance professional has:','["Paid a fee only", "Retired", "Joined a club", "Completed advanced coursework and passed exams"]'::jsonb,3,'Certifications show expertise.','original'),
('127.254.d.2.B',3,'An insurance agent''s role is mainly to:','["Help clients choose and buy coverage", "Approve loans", "Issue driver''s licenses", "Audit banks"]'::jsonb,0,'Agents advise buyers.','original'),
('127.254.d.2.B',4,'A claims adjuster differs from an underwriter because the adjuster:','["Sets state law", "Evaluates losses after they happen", "Sells policies", "Prices new applicants"]'::jsonb,1,'Adjusters handle claims; underwriters assess risk.','original'),
('127.254.d.3.A',3,'An agent who recommends only the highest-commission policy, even if it does not fit the client, is acting:','["Responsibly", "Wisely", "Unethically", "Legally required"]'::jsonb,2,'Clients'' interests come first.','original'),
('127.254.d.3.B',3,'In most states, insurance companies are primarily regulated by:','["The post office", "Schools", "Local police", "A state department of insurance"]'::jsonb,3,'Insurance is state regulated.','original'),
('127.254.d.3.B',4,'The McCarran-Ferguson Act of 1945 left regulation of the insurance business mostly to:','["The states", "Private clubs", "The Army", "Cities"]'::jsonb,0,'States regulate insurance.','original'),
('127.254.d.3.C',3,'COBRA allows certain workers who lose employer health coverage to:','["Get cash instead", "Continue that coverage temporarily by paying the premium", "Receive it free forever", "Skip the premium"]'::jsonb,1,'COBRA is continuation coverage.','original'),
('127.254.d.3.C',4,'A COBRA participant usually pays:','["Only a copay", "Half the premium", "The full premium plus a small administrative fee", "Nothing"]'::jsonb,2,'The employer no longer subsidizes it.','original'),
('127.254.d.3.D',3,'HIPAA is best known for protecting:','["Car titles", "Tax returns", "School grades", "The privacy and security of health information"]'::jsonb,3,'HIPAA covers health data.','original'),
('127.254.d.3.D',4,'Under HIPAA, an insurance office may share a patient''s health information with a friend only when:','["The patient authorizes it", "It is convenient", "It is free", "The friend asks"]'::jsonb,0,'Authorization is required.','original'),
('127.254.d.3.E',3,'The Patient Protection and Affordable Care Act (PPACA) prohibits insurers from denying coverage because of:','["Hair color", "Pre-existing conditions", "Home location", "Age of the car"]'::jsonb,1,'Pre-existing condition denials were banned.','original'),
('127.254.d.3.E',4,'Under PPACA, young adults may stay on a parent''s health plan until age:','["21", "30", "26", "18"]'::jsonb,2,'The dependent rule extends to 26.','original'),
('127.254.d.4.A',3,'The principle of indemnity means insurance should:','["Pay nothing", "Increase profit", "Pay more than the loss", "Restore a person to their pre-loss condition without profit"]'::jsonb,3,'Indemnity prevents gain.','original'),
('127.254.d.4.A',4,'Insurable interest means the buyer must:','["Stand to suffer a financial loss if the insured item is damaged", "Be the neighbor", "Be over 65", "Own a bank"]'::jsonb,0,'No interest means no policy.','original'),
('127.254.d.4.B',3,'An insurance contract is binding when there is an offer, acceptance, and:','["A hobby", "Consideration, usually the premium", "A rumor", "A holiday"]'::jsonb,1,'Consideration makes a contract valid.','original'),
('127.254.d.4.B',4,'An exclusion in an insurance contract is a provision that:','["Names the agent", "Cancels the premium", "Lists losses the policy does not cover", "Raises the benefit"]'::jsonb,2,'Exclusions limit coverage.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_45_v1'
from (values
('127.254.d.5.A',3,'Actuaries use statistics and probability to:','["Draft laws", "Sell policies", "Repair vehicles", "Estimate the likelihood and cost of future losses"]'::jsonb,3,'Actuaries price risk.','original'),
('127.254.d.5.A',4,'If 2 of every 1,000 insured homes suffer a $200,000 loss each year, the expected annual loss per home is:','["$400", "$40", "$2,000", "$200"]'::jsonb,0,'(2/1,000) x 200,000 = 400.','original'),
('127.254.d.5.B',3,'A credit-based insurance score uses information from a person''s:','["Social media", "Credit history to predict claim risk", "School grades", "Medical chart"]'::jsonb,1,'It is derived from credit data.','original'),
('127.254.d.5.B',4,'Many consumer groups criticize credit-based insurance scores because they may:','["Replace agents", "Cancel claims", "Raise rates for people with weaker credit even without claims", "Lower every rate"]'::jsonb,2,'Scores affect pricing.','original'),
('127.254.d.5.C',3,'During underwriting, the insurer decides whether to accept an applicant and at what:','["Weather", "Birthday gift", "Address style", "Premium or terms"]'::jsonb,3,'Underwriting selects and prices risk.','original'),
('127.254.d.5.C',4,'Underwriters often deny or surcharge an auto applicant who has:','["A history of serious accidents or violations", "A clean record", "A reliable car", "A new job"]'::jsonb,0,'Risky history raises cost.','original'),
('127.254.d.6.A',3,'A person who stages a car accident to collect payment commits:','["Good planning", "Insurance fraud", "A contract", "A deduction"]'::jsonb,1,'Staged accidents are fraud.','original'),
('127.254.d.6.A',4,'Padding a legitimate claim by adding items that were never lost is known as:','["Subrogation", "A discount", "Soft fraud", "Hard fraud only"]'::jsonb,2,'Soft fraud exaggerates real losses.','original'),
('127.254.d.6.B',3,'Insurers detect fraud by looking for patterns using:','["Coin flips", "Guesswork", "Rumors", "Data analysis and special investigation units"]'::jsonb,3,'Analytics flag suspicious claims.','original'),
('127.254.d.6.B',4,'A red flag for possible claim fraud is a loss reported:','["Soon after a policy was bought or increased", "With full receipts", "By a long-time customer", "With police report"]'::jsonb,0,'New policy plus quick loss is suspicious.','original'),
('127.254.d.6.C',3,'When researching a news story about insurance fraud, the most reliable source is:','["A joke site", "A court record or reputable news report", "A rumor", "An anonymous post"]'::jsonb,1,'Check credibility.','original'),
('127.254.d.6.C',4,'An effective summary of a fraud case includes who was involved, what happened, and:','["Their hobbies", "The weather", "The legal consequences", "Their favorite food"]'::jsonb,2,'Outcomes show impact.','original'),
('127.254.d.8.A',3,'A rating agency such as AM Best grades an insurer mainly on its:','["Advertising", "Office size", "Logo", "Financial strength and ability to pay claims"]'::jsonb,3,'Ratings show solvency.','original'),
('127.254.d.8.A',4,'A consumer should prefer an insurer with a high financial strength rating because it is:','["More likely to pay claims when needed", "Never audited", "Always cheaper", "Exempt from law"]'::jsonb,0,'Strong insurers remain solvent.','original'),
('127.254.d.8.B',3,'Young male drivers often pay more for auto insurance because statistics show higher:','["Incomes", "Claim rates for that group", "Fuel use", "Car values"]'::jsonb,1,'Rates reflect group risk.','original'),
('127.254.d.8.B',4,'Premiums for the same home often differ by geographic area because of local:','["Flag colors", "Mascots", "Weather, crime, and repair costs", "Street names"]'::jsonb,2,'Location affects risk.','original'),
('127.254.d.10.A',3,'A student exploring insurance careers would compare education, military service, and:','["Rumors", "Slogans", "Only hobbies", "Current job opportunities"]'::jsonb,3,'Options include several paths.','original'),
('127.254.d.10.B',3,'A postsecondary plan for an insurance career includes application deadlines, costs, and:','["Funding such as scholarships and aid", "Mascots", "Parking colors", "Dorm slogans"]'::jsonb,0,'Plans need financing.','original'),
('127.255.d.1.A',3,'Which event created the first national banking system and a uniform national currency in the 1860s?','["The Gold Rush", "The National Bank Acts", "The Louisiana Purchase", "The Homestead Act"]'::jsonb,1,'The National Banking Acts of 1863-64 created national banks.','original'),
('127.255.d.1.A',4,'The Federal Deposit Insurance Corporation was created in 1933 to:','["Collect taxes", "Print currency", "Insure bank deposits and restore public confidence", "Lend to homebuyers"]'::jsonb,2,'The FDIC followed bank failures.','original'),
('127.255.d.1.B',3,'The Federal Reserve System is the:','["Tax agency", "Largest private bank", "Court", "Central bank of the United States"]'::jsonb,3,'The Fed conducts monetary policy.','original'),
('127.255.d.1.B',4,'One tool the Federal Reserve uses to influence the economy is:','["Changing the federal funds target rate", "Printing stocks", "Paying wages", "Setting store prices"]'::jsonb,0,'Rate changes affect borrowing.','original'),
('127.255.d.1.C',3,'Under a gold standard, a nation''s currency can be exchanged for:','["Land", "A fixed amount of gold", "Rare coins only", "Any stock"]'::jsonb,1,'Currency was tied to gold.','original'),
('127.255.d.1.C',4,'The United States ended the dollar''s convertibility to gold in 1971 under President:','["Herbert Hoover", "Abraham Lincoln", "Richard Nixon", "Jimmy Carter"]'::jsonb,2,'The Nixon Shock ended Bretton Woods convertibility.','original'),
('127.255.d.1.D',3,'A financial institution that lends mainly for home purchases and historically took savings deposits is a:','["Insurance company", "Investment bank", "Stock exchange", "Savings and loan association"]'::jsonb,3,'S&Ls focused on home mortgages.','original'),
('127.255.d.1.D',4,'An investment bank primarily helps clients by:','["Underwriting securities and advising on mergers", "Cashing payroll checks", "Selling auto policies", "Offering checking accounts"]'::jsonb,0,'Investment banks arrange capital.','original'),
('127.255.d.1.E',3,'The World Bank Group''s main goal is to:','["Run exchanges", "Reduce poverty by funding development projects", "Print dollars", "Set U.S. taxes"]'::jsonb,1,'It lends for development.','original'),
('127.255.d.1.E',4,'Countries typically borrow from the World Bank to pay for:','["Sports events only", "Birthday parties", "Infrastructure such as roads, schools, and clean water", "Tax cuts only"]'::jsonb,2,'Funds go to development projects.','original'),
('127.255.d.1.F',3,'The Small Business Administration helps entrepreneurs mainly by:','["Setting prices", "Buying stores", "Printing money", "Guaranteeing loans made by approved lenders"]'::jsonb,3,'The SBA backs loans.','original'),
('127.255.d.1.F',4,'Which federal agency insures mortgages to help more families buy homes?','["The Federal Housing Administration", "The FDA", "The FTC", "The CIA"]'::jsonb,0,'FHA insures mortgages.','original'),
('127.255.d.2.A',3,'When a customer deposits a paycheck, the bank credits the account in a process called:','["Underwriting", "Posting the deposit", "Foreclosure", "Liquidation"]'::jsonb,1,'Posting updates balances.','original'),
('127.255.d.2.A',4,'Clearing a check means moving money from:','["The state to the city", "A store to a school", "The payer''s bank to the payee''s bank", "The IRS to a lender"]'::jsonb,2,'Clearing settles checks.','original'),
('127.255.d.2.B',3,'Safe deposit boxes and wire transfers are examples of:','["Loan products only", "Tax forms", "Investments only", "Banking services"]'::jsonb,3,'They are services offered by banks.','original'),
('127.255.d.2.B',4,'A bank wire transfer is useful for:','["Sending a large amount quickly and securely", "Printing checks", "Mailing cash", "Closing accounts"]'::jsonb,0,'Wires move funds fast.','original'),
('127.255.d.2.C',3,'Which is a retail bank product?','["Letter of credit", "Savings account", "Commercial paper", "Treasury cash management"]'::jsonb,1,'Retail products serve individuals.','original'),
('127.255.d.2.C',4,'A certificate of deposit usually pays a higher rate than savings in exchange for:','["No FDIC cover", "Daily access", "Leaving the money in for a set term", "No minimum"]'::jsonb,2,'CDs lock funds.','original'),
('127.255.d.2.D',3,'Which service is designed mainly for businesses?','["Piggy bank program", "Holiday club", "Student checking", "Merchant card processing"]'::jsonb,3,'Merchants accept card payments.','original'),
('127.255.d.2.D',4,'A business line of credit lets a company:','["Borrow up to a limit as needed and pay interest on what is used", "Skip repayment", "Print currency", "Borrow nothing ever"]'::jsonb,0,'Lines provide flexible funding.','original'),
('127.255.d.2.E',3,'A teller should balance the cash drawer:','["Never", "At the end of each shift and whenever required", "Once a year", "Only when the manager asks"]'::jsonb,1,'Drawers must reconcile.','original'),
('127.255.d.2.E',4,'Verifying a customer''s identity before a large withdrawal is part of teller:','["Advertising", "Decoration", "Security and accuracy standards", "Time off"]'::jsonb,2,'ID checks prevent fraud.','original'),
('127.255.d.2.F',3,'A loan secured by a car or house is called a:','["Unsecured loan", "Payday loan", "Gift", "Secured loan"]'::jsonb,3,'Collateral secures the loan.','original'),
('127.255.d.2.F',4,'An installment loan is repaid through:','["Regular scheduled payments", "Random payments", "One payment forever", "No payments"]'::jsonb,0,'Installments are scheduled.','original'),
('127.255.d.2.G',3,'A bank trust department can manage assets for:','["Only the government", "Beneficiaries under a trust", "Only the bank", "Only landlords"]'::jsonb,1,'Trusts are managed for beneficiaries.','original'),
('127.255.d.2.G',4,'A trustee''s duty is to manage trust assets:','["For personal gain", "Without records", "In the best interest of the beneficiaries", "For the bank''s profit only"]'::jsonb,2,'Fiduciary duty.','original'),
('127.255.d.3.A',3,'Which role at a bank typically handles records, scheduling, and customer paperwork?','["Board member", "Chief executive", "Regulator", "Administrative assistant"]'::jsonb,3,'Administrative staff support operations.','original'),
('127.255.d.3.A',4,'Strong accuracy and confidentiality skills are most important for bank staff who handle:','["Customer records", "Menu planning", "Parking lot paint", "Window decorations"]'::jsonb,0,'Records are sensitive.','original'),
('127.255.d.3.B',3,'A branch manager is responsible for:','["Printing money", "Operations, staff, and meeting branch goals", "Fixing ATMs only", "Setting national law"]'::jsonb,1,'Managers lead branches.','original'),
('127.255.d.3.B',4,'The chief financial officer of a bank oversees:','["Branch cleaning", "Window displays", "Financial reporting and planning", "Customer parking"]'::jsonb,2,'CFOs manage finances.','original'),
('127.255.d.4.A',3,'In banking, cross-selling means:','["Ignoring customers", "Closing accounts", "Selling the building", "Offering existing customers additional products"]'::jsonb,3,'Cross-selling deepens relationships.','original'),
('127.255.d.4.A',4,'A banker who learns a customer is buying a house and mentions a mortgage is practicing:','["Needs-based selling", "Fraud", "Avoidance", "Auditing"]'::jsonb,0,'Needs-based selling serves the customer.','original'),
('127.255.d.4.B',3,'Before opening a new account, a bank must verify the customer''s:','["Hair color", "Identity", "Favorite color", "Pet name"]'::jsonb,1,'Customer identification is required.','original'),
('127.255.d.4.B',4,'A signature card is used to:','["Set the rate", "Pay the rent", "Record who may sign on the account", "Print checks"]'::jsonb,2,'It authorizes signers.','original'),
('127.255.d.4.C',3,'A loan officer tells a client the loan has a 5-year term. The term is the:','["Amount borrowed", "Interest rate", "Collateral", "Length of time to repay the loan"]'::jsonb,3,'Term is the repayment period.','original'),
('127.255.d.4.C',4,'An annual percentage rate (APR) helps clients compare loans because it includes:','["Interest and certain fees", "Only the term", "Only the principal", "Only taxes"]'::jsonb,0,'APR shows total cost.','original'),
('127.255.d.5.A',3,'Dual control, where two employees must open the vault, helps prevent:','["Rate changes", "Internal theft", "Slow lines", "Rain damage"]'::jsonb,1,'Dual control adds checks.','original')
