('127.256.d.3.H',3,'Adjusting entries are made at the end of a period to:','["Change owners", "Update accounts for items such as supplies used", "Delete records", "Hide profit"]'::jsonb,1,'Adjustments match revenue and expenses.','original'),
('127.256.d.3.H',4,'Closing entries transfer balances of revenue and expense accounts to:','["Cash", "Supplies", "Owner''s capital or retained earnings", "Accounts payable"]'::jsonb,2,'Temporary accounts are zeroed.','original'),
