('127.256.d.4.B',4,'A deposit in transit is added to the:','["Checkbook balance", "Net income", "Bank statement balance", "Inventory"]'::jsonb,2,'Deposits not yet credited by the bank are added to the bank balance.','original'),
('127.256.d.4.C',3,'Petty cash is used to pay:','["Payroll taxes", "Large loans", "Rent for the year", "Small, minor expenses"]'::jsonb,3,'Petty cash handles small items.','original'),
