('127.256.d.7.H',3,'A schedule of accounts receivable lists:','["Each employee", "Each vendor", "Each bank", "Each customer and the amount owed"]'::jsonb,3,'The schedule totals receivables.','original'),
('127.256.d.7.H',4,'An aging schedule groups receivables by:','["How long they have been outstanding", "Customer''s age", "Product color", "Sales rep"]'::jsonb,0,'Aging shows overdue risk.','original'),
('127.256.d.7.I',3,'One method of estimating uncollectible accounts uses a percentage of:','["Equity", "Credit sales or receivables", "Payroll", "Cash"]'::jsonb,1,'Estimates use past experience.','original'),
('127.256.d.7.I',4,'If a company has $50,000 in receivables and estimates 4% will be uncollectible, the allowance is:','["$200", "$20,000", "$2,000", "$4,000"]'::jsonb,2,'0.04 x 50,000 = 2,000.','original'),
